		now: number,
		input: Pick<HevyHttpError, "status" | "headers">,
	) => Effect.runPromise(scheduleStep(now, input));
	const timeoutMs = normalizePositiveInteger(
		options.timeoutMs,
		DEFAULT_API_TIMEOUT_MS,
	);
